class ValidateFilter @Inject() (implicit val mat: Materializer, ec: ExecutionContext)
    extends Filter {
  def apply(nextFilter: RequestHeader => Future[Result])(requestHeader: RequestHeader): Future[Result] =
    IngressRules.check(requestHeader) match {
      case Some(error) => Future.successful(BadRequest(error))
      case None        => nextFilter(requestHeader)   // only validated requests continue
    }
}

def validate(routes: HttpRoutes[IO]): HttpRoutes[IO] = Kleisli { req =>
  IngressRules.check(req) match {
    case Left(error) => OptionT.pure[IO](BadRequest(error))
    case Right(_)    => routes(req)      // pass through only when valid
  }
}

val app = validate(routes).orNotFound

